package com.fctvclean.diag;
import android.app.*;import android.os.*;import android.security.keystore.*;import android.widget.*;import java.security.*;
public class MainActivity extends Activity{TextView v;public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);v=new TextView(this);v.setText("DIAG B — UI + AndroidKeyStore\n\nGenera una chiave RSA locale e firma solo la stringa TEST. Nessun APK viene aperto o installato.");Button x=new Button(this);x.setText("Test Keystore");x.setOnClickListener(q->go());l.addView(v);l.addView(x);setContentView(l);}void go(){try{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);String a="fctv_diag_b";if(!ks.containsAlias(a)){KeyPairGenerator g=KeyPairGenerator.getInstance(KeyProperties.KEY_ALGORITHM_RSA,"AndroidKeyStore");g.initialize(new KeyGenParameterSpec.Builder(a,KeyProperties.PURPOSE_SIGN|KeyProperties.PURPOSE_VERIFY).setKeySize(2048).setDigests(KeyProperties.DIGEST_SHA256).setSignaturePaddings(KeyProperties.SIGNATURE_PADDING_RSA_PKCS1).build());g.generateKeyPair();}Signature s=Signature.getInstance("SHA256withRSA");s.initSign((PrivateKey)ks.getKey(a,null));s.update("TEST".getBytes());v.append("\n\nOK firma: "+s.sign().length+" byte");}catch(Exception e){v.append("\nERRORE: "+e);}}}
